<?php namespace App\Controllers; class Transfers extends BaseController{public function index(){if($r=$this->mustLogin())return $r;$month=$this->request->getGet('month')?:date('Y-m');$db=db_connect();$rows=$db->query("SELECT d.entry_date,m.code,m.description,d.transfer_out_qty,d.transfer_challan_no,u.name user_name FROM daily_entries d JOIN materials m ON m.id=d.material_id JOIN users u ON u.id=d.created_by WHERE d.month_key=? AND d.transfer_out_qty>0 ORDER BY d.entry_date DESC",[$month])->getResultArray();return $this->render('transfers/index',['pageTitle'=>'Transfers','month'=>$month,'rows'=>$rows]);}}